/* eslint-disable */
import gql from 'graphql-tag';
import * as Apollo from '@apollo/client';
export type Maybe<T> = T;
export type InputMaybe<T> = T;
export type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
export type MakeOptional<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]?: Maybe<T[SubKey]> };
export type MakeMaybe<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]: Maybe<T[SubKey]> };
export type MakeEmpty<T extends { [key: string]: unknown }, K extends keyof T> = { [_ in K]?: never };
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
const defaultOptions = {} as const;
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  /** A Byte scalar type represents a signed 8-bit numeric non-fractional value */
  Byte: { input: any; output: any; }
  /** A scalar which represents java.lang.Character */
  Char: { input: any; output: any; }
  /** An RFC-3339 (ISO-8601) compliant date scalar that accepts string values like 1996-12-19 */
  Date: { input: any; output: any; }
  /** An RFC-3339 (ISO-8601) compliant date time scalar that accepts string values like 1996-12-19T16:39:57-08:00 */
  DateTime: { input: any; output: any; }
  /**
   * A scalar which represents fixed point/precision decimal numbers
   * JavaScript (TypeScript), Python equivalent: Decimal
   * We will decide later on how these values are represented on the wire
   */
  Decimal: { input: any; output: any; }
  /**
   * Error specific (not for general use) scalar that could accept both String and Int as defined in
   * https://github.intuit.com/pages/intuit-one-api/one-api-standards-governance/#/GraphQL/graphql-guidelines?id=_62-use-error-extensions-to-encode-additional-information-for-errors-portion-of-the-response
   */
  ErrorPathElement: { input: any; output: any; }
  /**
   * A synonym for the Object scalar, it will accept any object as a scalar value
   *
   * One of the design goals of GraphQL, is that the type system describes the shape of the data returned.
   *
   * The Object / JSON scalars work against this some what because they can return compound values outside the type system. As such they should be used sparingly. In general your should aim to describe the data via the GraphQL type system where you can and only resort to the Object / JSON scalars in very rare circumstances.
   *
   * An example might be an extensible GraphQL system where systems can input custom metadata objects that cant be known at schema type design time.
   */
  JSON: { input: any; output: any; }
  /** The Locale scalar handles IETF BCP 47 language tags */
  Locale: { input: any; output: any; }
  /** A Long scalar type represents a signed 64-bit numeric non-fractional value */
  Long: { input: any; output: any; }
  /** An Int scalar that represents a non-negative 32-bit numeric non-fractional value. */
  NonNegativeInt: { input: any; output: any; }
  /** An object scalar that accepts any object as a scalar value. */
  Object: { input: any; output: any; }
  /** An Float scalar type represents positive double-precision finite values as specified by IEEE 754 */
  PositiveFloat: { input: any; output: any; }
  /** An Int scalar that represents a positive 32-bit numeric non-fractional value. */
  PositiveInt: { input: any; output: any; }
  /** A Long scalar type represents a positive 64-bit numeric non-fractional value */
  PositiveLong: { input: any; output: any; }
  /** A Short scalar type represents a positive 16-bit numeric non-fractional value */
  PositiveShort: { input: any; output: any; }
  /** A Short scalar type represents a signed 16-bit numeric non-fractional value */
  Short: { input: any; output: any; }
  /** An RFC-3339 (ISO-8601) compliant time scalar that accepts string values like 16:39:57-08:00 */
  Time: { input: any; output: any; }
  /**
   * Mutation specific error code, represented as a string. See the documentation for each mutation to see which error codes can be returned.
   * *This list may be extended in the future. If an unknown error code is encountered, treat it as a `GENERAL_ERROR`.*
   *
   * - `GENERAL_ERROR`
   * - This error will be returned when we encounter an error that does not yet have a specific code attached to it. These are logged and a more specific code will become part of the above list as they are discovered.
   *
   * - `BILLABLE_REQUIRES_CUSTOMER`
   * - This error will be returned when a billable time entry does not have a customer set on it.
   *
   * - `START_AND_END_TIME_REQUIRED_WHEN_ONE_PRESENT`
   * - This error will be returned when either the start time or end time is present but the other is not.
   *
   * - `START_TIME_MUST_BE_BEFORE_END_TIME`
   * - This error will be returned when the start time is after the end time.
   *
   * - `CUSTOMER_CURRENCY_MUST_MATCH_COMPANY_CURRENCY`
   * - This error will be returned when customer currency does not match with company currency.
   *
   * - `SALES_MUST_HAVE_CUSTOMER`
   * - This error will be returned when customer is not selected for billable Time entry.
   *
   * - `TT_DURATION_NOT_MATCHED`
   * - This error will be returned break time is greater than total time.
   *
   * - `TT_BREAK_DURATION_INVALID`
   * - This error will be returned when break is not valid.
   *
   * - `START_END_TIME_AND_DURATION_CANNOT_BE_PROVIDED_TOGETHER`
   * - This error will be returned when start time, end time and duration are provided together.
   *
   * - `START_END_TIME_OR_DURATION_REQUIRED`
   * - This error will be returned when neither start time and end time or duration are provided.
   *
   * - `DURATION_MUST_BE_LESS_THAN_9999_HOURS`
   * - This error will be returned when duration is greater than 9999 hours.
   *
   * - `BREAK_DURATION_MUST_BE_LESS_THAN_9999`
   * - This error will be returned when break duration is greater than 9999 hours.
   *
   * - `BREAK_DURATION_INVALID_OR_LESS_THAN_ZERO`
   * - This error will be returned when break duration is invalid or less than zero.
   *
   * - `ALREADY_CLOCKED_IN`
   * - This error will be returned when worker is already clocked in.
   *
   * - `CLOCKIN_START_TIME_IN_FUTURE`
   * - This error will be returned when clock in time is in future from current time.
   *
   * - `CONFLICTING_TIME_ENTRY`
   * - This error will be returned when time entry is conflicting with existing time entry on doing clock in
   *
   * - `START_OR_END_TIME_IN_FUTURE`
   * - This error will be returned when start or end time is in future from current time for regular timesheet entry for clock in/out.
   *
   * - `CONFLICTING_START_TIME_ENTRY`
   * - This error will be returned when start time is conflicting with existing time entry for regular timesheet
   *
   * - `CONFLICTING_END_TIME_ENTRY`
   * - This error will be returned when end time is conflicting with existing time entry for regular timesheet
   *
   * - `CONFLICTING_START_END_TIME_ENTRY`
   * - This error will be returned when start and end time is conflicting with existing time entry for regular timesheet
   *
   * - `TIME_FOR_ID_MISSING`
   * - This error will be returned when timeFor id is missing for regular/manual timesheet entry
   *
   * - `START_END_TIME_OR_DURATION_MISSING`
   * - This error will be returned when neither start time and end time or duration are provided for any kind of time entry creation
   *
   * - `BREAK_RULE_NOT_FOUND`
   * - This error will be returned when break rule is not found for the given break policy id and worker id.
   *
   * - `MANUAL_MODE_NOT_ALLOWED`
   * - This error will be returned when manual mode is not allowed for the given break policy id.
   *
   * - `MANUAL_RULE_NOT_DEFINED`
   * - This error will be returned when manual rule is not defined for the given break policy id.
   *
   * - `INVALID_BREAK_DURATION`
   * - This error will be returned when break duration is invalid for the given break policy id for start_end based break time entry creation.
   *
   * - `DUPLICATE_ESTIMATE`
   * - This error will be returned when an attempt is made to create an estimate for a project that already has an active estimate.
   *
   * - `ESTIMATE_NOT_FOUND`
   * - This error will be returned when no active estimate is found for the specified project during update or delete.
   *
   * - `ESTIMATE_TYPE_CANNOT_BE_CHANGED`
   * - This error will be returned when an update mutation attempts to change the estimate type of an existing estimate. Estimate type is immutable after creation.
   *
   * - `PROJECT_NOT_FOUND`
   * - This error will be returned when DAS validation fails because the specified project does not exist or is not a valid time-against entity.
   *
   * - `FIELD_OPTION_NOT_FOUND`
   * - This error will be returned when CES validation fails because a specified field option does not exist or does not belong to the specified field.
   */
  TimeTracking_ErrorCode: { input: any; output: any; }
  /** Mutation specific success code, represented as a string. See the documentation for each mutation to see which success codes can be returned. */
  TimeTracking_SuccessCode: { input: any; output: any; }
  /** A universally unique identifier scalar that accepts uuid values like 2423f0a0-3b81-4115-a189-18df8b35e8fc */
  UUID: { input: any; output: any; }
  /** An url scalar that accepts string values like https://www.w3.org/Addressing/URL/url-spec.txt */
  Url: { input: any; output: any; }
};

