/** TimeTracking mutations */
export type Mutation = {
  __typename?: 'Mutation';
  /**
   * Assigns managers to a group.
   * A worker can manage multiple groups without being a member.
   * Supports bulk operations with partial success reporting.
   */
  timeTrackingAssignGroupManagers?: Maybe<TimeTracking_AssignGroupManagersResult>;
  /**
   * Assigns members to a group.
   * A worker can only be a member of one active group at a time.
   * Supports bulk operations with partial success reporting.
   */
  timeTrackingAssignGroupMembers?: Maybe<TimeTracking_AssignGroupMembersResult>;
  /**
   * Creates, updates, or deletes Time entries in a batch action.
   * Can be used to create new Time entries in batch.
   * Can be used to update Time entries in batch.
   * Can be used to delete Time entries in batch.
   * This API mimics the V1 qbo api and does all actions in a single transaction.
   */
  timeTrackingBatchManageTimeEntries?: Maybe<TimeTracking_BatchManageTimeEntriesResult>;
  /**
   * Creates attachments for a time entry or a post.
   * Provide exactly one of timeEntryId or postId in the input.
   */
  timeTrackingCreateAttachments?: Maybe<TimeTracking_CreateAttachmentsResult>;
  /**
   * Creates a single geofence flag.
   * Entity associations are created separately via timeTrackingCreateFlagMaps.
   */
  timeTrackingCreateFlag?: Maybe<TimeTracking_CreateFlagResult>;
  /**
   * Creates entity associations linking an existing flag to time entries and/or location points.
   * Multiple entities can be linked to a single flag in one call.
   */
  timeTrackingCreateFlagMaps?: Maybe<TimeTracking_CreateFlagMapsResult>;
  /**
   * Creates a new group.
   * Group name must be unique within the company.
   * Use separate assign mutations to add members and managers.
   */
  timeTrackingCreateGroup?: Maybe<TimeTracking_CreateGroupResult>;
  /** Mutation to record a collection of location points for a user */
  timeTrackingCreateLocationPoints?: Maybe<TimeTracking_CreateLocationPointsResult>;
  /**
   * Creates a new project estimate.
   * Supports TOTAL_HOURS (single budget) and BY_FIELD_OPTION (per-option breakdown by Standard Field or Custom Field).
   * Returns DUPLICATE_ESTIMATE if an active estimate already exists for the project.
   * To switch estimate type, delete the existing estimate first and then create a new one.
   */
  timeTrackingCreateProjectEstimate?: Maybe<TimeTracking_CreateProjectEstimateResult>;
  /**
   * Creates a Time Entry with the given input.
   * Can only be used to create new TimeEntries.
   */
  timeTrackingCreateTimeEntry?: Maybe<TimeTracking_CreateTimeEntryResult>;
  /**
   * Deletes attachments from a time entry or a post.
   * When postId is present in the input, deletes content attachments; otherwise deletes time entry attachments.
   */
  timeTrackingDeleteAttachments?: Maybe<TimeTracking_DeleteAttachmentsResult>;
  /**
   * Soft-deletes a group by setting isActive to false.
   * Group and relationships are preserved for audit.
   * Deleted groups are excluded from default queries.
   */
  timeTrackingDeleteGroup?: Maybe<TimeTracking_DeleteGroupResult>;
  /**
   * Soft-deletes a post or reply and all associated content attachments.
   * Cannot delete a post that has active (non-deleted) replies — returns HAS_ACTIVE_REPLIES error.
   * Dual-sync: syncs to TSheets synchronously via PostDualSyncFacade before persisting locally.
   */
  timeTrackingDeletePost?: Maybe<TimeTracking_DeletePostResult>;
  /**
   * Soft-deletes the active estimate for a project.
   * Sets is_active=false on the estimate and all its estimate items in a single transaction.
   * Also deactivates the corresponding TSheets estimate.
   * Returns ESTIMATE_NOT_FOUND if no active estimate exists for the project.
   */
  timeTrackingDeleteProjectEstimate?: Maybe<TimeTracking_DeleteProjectEstimateResult>;
  /** Deletes a Time entry with the given input. */
  timeTrackingDeleteTimeEntry?: Maybe<TimeTracking_DeleteTimeEntryResult>;
  /** Manage assignments for a custom field (customers) */
  timeTrackingManageCustomFieldAssignment?: Maybe<TimeTracking_ManageCustomFieldAssignmentResult>;
  /** Manage assignments for a custom field option (workers) */
  timeTrackingManageCustomFieldOptionAssignment?: Maybe<TimeTracking_ManageCustomFieldOptionAssignmentResult>;
  /** Manage time against assignments for a custom field option */
  timeTrackingManageCustomFieldOptionTimeAgainstAssignment?: Maybe<TimeTracking_ManageCustomFieldOptionTimeAgainstAssignmentResult>;
  /** Mutation to manage custom fields */
  timeTrackingManageCustomFields?: Maybe<TimeTracking_ManageCustomFieldsResult>;
  /**
   * Creates or updates a post/reply.
   *
   * Operation determined by input:
   * - id absent → create (parentPostId determines top-level post vs reply)
   * - id present → update
   *
   * Attachments are managed separately via timeTrackingCreateAttachments / timeTrackingDeleteAttachments.
   * Dual-sync: syncs to TSheets synchronously via PostDualSyncFacade before persisting locally.
   */
  timeTrackingManagePost?: Maybe<TimeTracking_ManagePostResult>;
  /** Manage assignments for a standard field (customers) */
  timeTrackingManageStandardFieldAssignment?: Maybe<TimeTracking_ManageStandardFieldAssignmentResult>;
  /** Manage assignments for a standard field option (customer/project) */
  timeTrackingManageStandardFieldOptionTimeAgainstAssignment?: Maybe<TimeTracking_ManageStandardFieldOptionTimeAgainstAssignmentResult>;
  /** Manage assignments for a standard field option (workers) */
  timeTrackingManageStandardFieldOptionTimeForAssignment?: Maybe<TimeTracking_ManageStandardFieldOptionTimeForAssignmentResult>;
  /** Manage custom/standard field assignments for a timeAgainst */
  timeTrackingManageTimeAgainstFieldAssignment?: Maybe<TimeTracking_ManageTimeAgainstFieldAssignmentResult>;
  /** Manage worker assignments for a customer/project */
  timeTrackingManageTimeAgainstTimeForAssignment?: Maybe<TimeTracking_ManageTimeAgainstTimeForAssignmentResult>;
  /**
   * Manage user-specific unified settings (create or update).
   *
   * Version handling:
   * - For new settings: omit version or pass null
   * - For updates: pass current version for optimistic locking
   */
  timeTrackingManageUnifiedUserSettings?: Maybe<TimeTracking_ManageUnifiedUserSettingsResult>;
  /** Manage user-specific time tracking settings */
  timeTrackingManageUserSettings?: Maybe<TimeTracking_ManageUserSettingsResult>;
  /**
   * Marks posts as read up to a watermark timestamp for the current worker.
   * Updates post_read_tracking table (entity_type = PROJECT for feed-level, POST for reply-level).
   * All posts/replies with createdAt <= readTo are considered read.
   */
  timeTrackingMarkPostsRead?: Maybe<TimeTracking_MarkPostsReadResult>;
  /**
   * Removes managers from a group.
   * Does not affect manager's membership in the group.
   * Supports bulk operations with partial success reporting.
   */
  timeTrackingRemoveGroupManagers?: Maybe<TimeTracking_RemoveGroupManagersResult>;
  /**
   * Removes members from a group.
   * Supports bulk operations with partial success reporting.
   */
  timeTrackingRemoveGroupMembers?: Maybe<TimeTracking_RemoveGroupMembersResult>;
  /** Resets user settings to their default values */
  timeTrackingResetUserSettings?: Maybe<TimeTracking_ResetUserSettingsResult>;
  /**
   * Submits a worker's time (Submit Time feature) by updating the worker's `submittedTo`
   * date in TSheets via PUT /api/v1/users. The worker is first resolved from the local
   * workers store using `workerId` + `workerType`; the resolved TSheets numeric id is used
   * for the upstream call. `submittedTo` is an exclusive end — the client applies the
   * +1-day / full-week math and Quantum Leap forwards the value verbatim. Authorized for
   * the worker themselves (self) or an admin.
   */
  timeTrackingSubmitWorkerTime?: Maybe<TimeTracking_SubmitWorkerTimeResult>;
  /** Updates the approval settings for time tracking */
  timeTrackingUpdateApprovalSettings?: Maybe<TimeTracking_UpdateApprovalSettingsResult>;
  /** Updation of attachment metadata for the time entry */
  timeTrackingUpdateAttachments?: Maybe<TimeTracking_UpdateAttachmentsResult>;
  /** Updates the given employer settings for time tracking */
  timeTrackingUpdateEmployerSettings?: Maybe<TimeTracking_UpdateEmployerSettingsResult>;
  /** Updates geofence configuration (radius, enabled) for a customer or project */
  timeTrackingUpdateGeofenceConfiguration?: Maybe<TimeTracking_UpdateGeofenceConfigurationResult>;
  /**
   * Updates an existing group's name.
   * Requires version number for optimistic locking.
   * Use deleteGroup mutation to soft-delete a group.
   */
  timeTrackingUpdateGroup?: Maybe<TimeTracking_UpdateGroupResult>;
  /**
   * Updates an existing active project estimate.
   * For TOTAL_HOURS: no additional fields needed — total is derived from estimate items.
   * For BY_FIELD_OPTION: replaces the full item list (diff applied server-side — new items inserted, changed items updated,
   * removed items soft-deleted).
   * Estimate type is immutable — returns ESTIMATE_TYPE_CANNOT_BE_CHANGED if estimateType in the input differs from the current value.
   * Returns ESTIMATE_NOT_FOUND if no active estimate exists for the project.
   */
  timeTrackingUpdateProjectEstimate?: Maybe<TimeTracking_UpdateProjectEstimateResult>;
  /**
   * Updates a Time entry with the given input.
   * Requires a valid Time entry ID to update.
   * Can be a sparse update with the sparse field.
   */
  timeTrackingUpdateTimeEntry?: Maybe<TimeTracking_UpdateTimeEntryResult>;
  /**
   * Updates worker permissions for a single worker. Accepts structured permission fields
   * (admin, management, schedule, project, and feature); the service maps each field to
   * Identity RPAS ADD/DELETE operations.
   */
  timeTrackingUpdateWorkerPermissions?: Maybe<TimeTracking_UpdateWorkerPermissionsResult>;
};


