/** TimeTracking queries */
export type Query = {
  __typename?: 'Query';
  /** Query to fetch the time tracking approval settings */
  timeTrackingApprovalSettings?: Maybe<TimeTracking_ApprovalSettings>;
  timeTrackingAttachments?: Maybe<TimeTracking_AttachmentInfoConnection>;
  /** Query to fetch custom dimensions with defaults for time tracking */
  timeTrackingCustomDimensions?: Maybe<TimeTracking_CustomDimensionsConnection>;
  /** Query to fetch custom fields with their assignment status based on scope and filter criteria */
  timeTrackingCustomFieldAssignments?: Maybe<TimeTracking_CustomFieldAssignmentsConnection>;
  /** Query to fetch custom field options with their assignment status based on scope and filter criteria */
  timeTrackingCustomFieldOptionAssignments?: Maybe<TimeTracking_CustomFieldOptionAssignmentConnection>;
  /** Query to fetch custom fields */
  timeTrackingCustomFields?: Maybe<TimeTracking_CustomFieldDefinitionConnection>;
  /** Query to fetch time summary aggregated by customer */
  timeTrackingCustomerTimeSummary?: Maybe<TimeTracking_CustomerTimeSummaryConnection>;
  /** Query to return the effective user settings which include default employer settings when user settings are not defined */
  timeTrackingEffectiveUserSettings?: Maybe<TimeTracking_EffectiveUserSettings>;
  /** Fetches the timeTracking related employer setting */
  timeTrackingEmployerSettings?: Maybe<TimeTracking_EmployerSettings>;
  /** Fetches geofence configuration for one or more customers or projects */
  timeTrackingGeofenceConfiguration?: Maybe<TimeTracking_GeofenceConfigurationConnection>;
  /** Fetches geofence radius */
  timeTrackingGeofenceRadius?: Maybe<TimeTracking_GeofenceRadiusResult>;
  /** Retrieves groups with filtering, ordering, and pagination support */
  timeTrackingGroups?: Maybe<TimeTracking_GroupConnection>;
  /**
   * Query to fetch complete location details for a specific time entry.
   * This includes all location points recorded during the time entry period, along with start and end locations,
   * and current time entry status.
   * Note: Although this query will be used to return all the location points, we would be supporting pagination with a default size of 1000 entries.
   */
  timeTrackingLocationDetail?: Maybe<TimeTracking_LocationDetail>;
  /**
   * Returns customers or projects near the worker's current location, sorted by distance ascending.
   * Only returns entities assigned to the requesting worker that have a successfully geocoded address.
   * Geofence does not need to be enabled — any customer with a geocoded address qualifies.
   */
  timeTrackingNearbyCustomers?: Maybe<TimeTracking_NearbyCustomersConnection>;
  /** Provides a summary of time tracked to employee compensations for a given time period, only considered approved data unless the customer has opted out of approvals */
  timeTrackingPayrollEmployeeData?: Maybe<TimeTracking_PayrollEmployeeDataConnection>;
  /**
   * Paginated posts for a project.
   *
   * Three modes controlled by filter:
   * - Feed mode (filter absent or both fields absent): top-level posts (parentPostId IS NULL).
   * - Single-post mode (filter.id present): returns that specific post only.
   *   id takes precedence — if both id and parentPostId are provided, parentPostId is ignored.
   * - Replies mode (filter.parentPostId present, id absent): returns direct children of that post.
   *
   * Sort: createdAt DESC for feed, createdAt ASC for replies.
   * Authorization: defaultAuthZService.authorize(AuthZResource.POST, AuthZAction.READ).
   * Self-scope: validates user is assigned to project's job code via DAS.
   */
  timeTrackingPosts?: Maybe<TimeTracking_PostsConnection>;
  /**
   * Returns the total count of unread top-level posts for a worker in a project feed.
   * Lightweight query optimized for polling (e.g., badge count on the posts tab).
   * Compares post createdAt against the worker's PROJECT-level read watermark.
   */
  timeTrackingPostsUnreadCount?: Maybe<TimeTracking_PostsUnreadCountResult>;
  /**
   * Retrieves a paginated list of project estimates.
   * For the detail view of a single project, filter by `projectRefs` and request `projectEstimateItems` on each
   * `TimeTracking_ProjectEstimate` node.
   * Returns null `projectEstimateItems` for TOTAL_HOURS estimates.
   * For BY_FIELD_OPTION with fieldRef = SERVICE_ITEM, `projectEstimateItems` may include a synthetic
   * "Others" row (fieldOptionId "-1") for elapsed time logged on the project without a service item;
   * see `TimeTracking_FieldOptionEstimate`.
   */
  timeTrackingProjectEstimates?: Maybe<TimeTracking_ProjectEstimatesConnection>;
  /** Query to fetch standard field assignment summary data with statistics */
  timeTrackingStandardFieldAssignmentSummary?: Maybe<TimeTracking_StandardFieldAssignmentSummaryConnection>;
  /** Query to fetch standard fields with their assignment status based on scope and filter criteria */
  timeTrackingStandardFieldAssignments?: Maybe<TimeTracking_StandardFieldAssignmentsConnection>;
  /**
   * Retrieves standard field options (CLASS, LOCATION, SERVICE_ITEM) with assignment status for a given worker, customer, or project
   * Enables filtering by assignment and active status with cursor-based pagination
   * Returns one edge per option, allowing efficient pagination through large option lists
   */
  timeTrackingStandardFieldOptionAssignments?: Maybe<TimeTracking_StandardFieldOptionAssignmentConnection>;
  /** Query to fetch standard field options (CLASS, LOCATION, SERVICE_ITEM, BILLABLE) with assignment summary counts for workers and customers */
  timeTrackingStandardFieldOptionSummary?: Maybe<TimeTracking_StandardFieldOptionSummaryConnection>;
  /** Fetches distinct time against field by usage pattern from time-entries */
  timeTrackingTimeAgainst?: Maybe<TimeTracking_TimeAgainstConnection>;
  /** Query to fetch time against entities with their assignment summary and statistics */
  timeTrackingTimeAgainstAssignmentSummary?: Maybe<TimeTracking_TimeAgainstAssignmentSummaryConnection>;
  /** Query to fetch time against entities with their assignment status based on scope and filter criteria */
  timeTrackingTimeAgainstAssignments?: Maybe<TimeTracking_TimeAgainstAssignmentConnection>;
  /**
   * Query to fetch the time cost summary, it supports both offset and cursor pagination
   * But at a time only one should be used
   */
  timeTrackingTimeCostSummary?: Maybe<TimeTracking_TimeCostSummaryConnection>;
  /** Queries a list of Time entries for the given input. */
  timeTrackingTimeEntries?: Maybe<TimeTracking_TimeEntriesConnection>;
  /** Queries a of Time entries for the Id. */
  timeTrackingTimeEntry?: Maybe<TimeTracking_TimeEntry>;
  /** Query to fetch workers with their assignment status based on scope and filter criteria */
  timeTrackingTimeForAssignments?: Maybe<TimeTracking_TimeForAssignmentsConnection>;
  /** Fetches the total duration by date. */
  timeTrackingTotalDurationByDate?: Maybe<TimeTracking_TotalDurationByDateConnection>;
  /** Query to fetch the total worked duration for a user in a given time window by week OR month */
  timeTrackingTotalDurationByTimeWindow?: Maybe<TimeTracking_TotalDurationByTimeWindow>;
  /** Query to retrieve user-specific unified settings. */
  timeTrackingUnifiedUserSettings?: Maybe<TimeTracking_UnifiedUserSettings>;
  /** Query to retrieve user settings that have been defined for the given user */
  timeTrackingUserSettings?: Maybe<TimeTracking_UserSettings>;
  /**
   * Returns a paginated collection of workers with their current time tracking status,
   * location data, and work details. Supports multiple filter modes and sorting options.
   */
  timeTrackingWhoIsWorking: TimeTracking_WhoIsWorkingConnection;
  /**
   * Query to fetch worker permissions for a single worker. Returns admin, management,
   * schedule, project, and feature permission flags mapped from Identity RPAS roles.
   *
   * Worker ID uses the same identifiers as timeTrackingWorkers. Returns null if the worker
   * does not exist or the caller lacks access.
   */
  timeTrackingWorkerPermissions?: Maybe<TimeTracking_WorkerPermissions>;
  /**
   * Fetches a worker's submit-time dates (submittedTo / approvedTo) used by the Submit Time flow
   * to compute the date range before fetching timesheets. Resolves the worker from the local
   * workers store using `workerId` + `workerType`, then reads the dates from TSheets.
   * Authorized for the worker themselves (self) or an admin. Returns null if the worker does not
   * exist or the caller lacks access.
   */
  timeTrackingWorkerSubmitTimeDates?: Maybe<TimeTracking_WorkerSubmitTimeDates>;
  /**
   * Query to fetch worker time summary. Provides total work time, regular time, and billable
   * time for each worker with filtering, ordering, and cursor-based pagination.
   *
   * Supports optional scoping by date range, project, service item, or specific worker IDs.
   * All filter fields are optional — combine them to narrow results (e.g. project + serviceItemId
   * to see per-worker hours for a specific service item on a project).
   */
  timeTrackingWorkerTimeSummary?: Maybe<TimeTracking_WorkerTimeSummaryConnection>;
  /** Fetch all time tracking workers for a company with filtering, sorting, and pagination */
  timeTrackingWorkers?: Maybe<TimeTracking_WorkerConnection>;
  /** Workers who have time entries in a date range; uses type+id and workerDASInfo for DAS stitching. */
  timeTrackingWorkersWithTimeEntries?: Maybe<TimeTracking_WorkersWithTimeEntriesConnection>;
};


