/**
 * A single line item in a BY_FIELD_OPTION estimate — the estimated seconds for one field option.
 * Maps to TSheets estimate_items with a specific tag_id.
 */
export type TimeTracking_FieldOptionEstimate = {
  __typename?: 'TimeTracking_FieldOptionEstimate';
  /**
   * Elapsed time in seconds logged by workers against this project scoped to this field option.
   * Only populated for fieldType = STANDARD_FIELD and fieldRef = SERVICE_ITEM.
   * Returns 0 for all other field types (CLASS, LOCATION, CUSTOM_FIELD).
   */
  elapsedSeconds: Scalars['Long']['output'];
  /**
   * Estimated seconds for this field option.
   *
   * Read path: for virtual rows (elapsed without a persisted estimate line, including the synthetic
   * "Others" row for time with no service item), this value is -1 so the UI can distinguish them
   * from real estimates (0 is a valid budget).
   */
  estimatedSeconds: Scalars['Long']['output'];
  /**
   * The ID of the field option (e.g. a specific service item, class, location, or custom field option).
   * Maps to TSheets tag_id.
   *
   * Read path only: for SERVICE_ITEM estimates, a synthetic "Others" row may appear with
   * `fieldOptionId` "-1" when workers logged time on the project with no service item tagged.
   * That row is not a real tag_id; use it for a dedicated UI tab. Real service item IDs are positive.
   */
  fieldOptionId: Scalars['ID']['output'];
  /**
   * DAS reference to the QuickBooks service item (Product) for this estimate line item.
   * Populated only when the parent estimate has fieldRef = SERVICE_ITEM; null otherwise.
   * The supergraph auto-stitches this to the full DataAccess_Product entity.
   * Null on the synthetic "Others" row (`fieldOptionId` "-1").
   */
  serviceItemDAS?: Maybe<DataAccess_Product>;
};

