/**
 * A single notification subscription row, reusable across any notification
 * category. Identifies the trigger via notificationType and the channels the
 * subscriber wants delivery on. Generic across categories; category-specific
 * semantics are conveyed by the parent wrapper field (e.g. scheduleNotifications.subscriptions).
 */
export type TimeTracking_NotificationSubscription = {
  __typename?: 'TimeTracking_NotificationSubscription';
  /**
   * Delivery channels the subscriber has enabled for this notification type.
   * An empty list means the subscription exists but no channels are active
   * (treated by the server as disabled — matches the tsheets enabled=0
   * derivation when distributionMethods is empty).
   */
  distributionMethods: Array<TimeTracking_NotificationReminderMedium>;
  /** Audit metadata (created by, modified by, timestamps) for this subscription row. */
  meta?: Maybe<TimeTracking_SettingMeta>;
  /**
   * The trigger this subscription is configured for. The server enforces that
   * the value belongs to the category wrapper this subscription appears under.
   */
  notificationType: TimeTracking_NotificationType;
};

/**
 * Input for a single notification subscription row, reusable across categories
 * on both the company and user sides. Identified per-scope by notificationType
 * (matches the DDL unique constraint); writers upsert by this key rather than
 * sending separate create/update/delete arrays.
 */
export type TimeTracking_NotificationSubscriptionInput = {
  /**
   * Delivery channels to enable for this notification type. Pass an empty
   * list to express "subscribed but no channels active" — the server derives
   * enabled=false from an empty list (matches tsheets behavior). There is no
   * separate enabled field in this input by design.
   */
  distributionMethods: Array<TimeTracking_NotificationReminderMedium>;
  /**
   * The trigger this row applies to. The server enforces that the value
   * belongs to the category wrapper this input appears under.
   */
  notificationType: TimeTracking_NotificationType;
  /**
   * Optimistic-lock version for this subscription row, sourced from
   * TimeTracking_NotificationSubscription.meta.version on a prior read.
   * Required when the subscription row already exists (server rejects a
   * stale or missing version with an optimistic-lock error). Omit when
   * the row does not yet exist — server treats absence as a first-time
   * create. Versioning is per-row (one per notificationType + entity
   * scope), not per-field.
   */
  version?: InputMaybe<Scalars['String']['input']>;
};

/**
 * Shared enum identifying a notification subscription's trigger across all notification
 * categories (schedule, future time-off, future clock-in/out, etc.). Every value's
 * description specifies which category it belongs to. The server validates on write
 * that the supplied value matches the category wrapper it appears under
 * (e.g. schedule values are only allowed under scheduleNotifications); the schema
 * itself does not enforce this constraint.
 */
export enum TimeTracking_NotificationType {
  /**
   * Schedule category — fires at a configurable time offset after a shift's
   * scheduled end when the worker has not yet clocked out.
   */
  ShiftEndAfter = 'SHIFT_END_AFTER',
  /**
   * Schedule category — fires for each subscriber when a shift is published or
   * re-published to them.
   */
  ShiftPublished = 'SHIFT_PUBLISHED',
  /**
   * Schedule category — fires at a configurable time offset after a shift's
   * scheduled start when the worker has not yet clocked in.
   */
  ShiftStartAfter = 'SHIFT_START_AFTER',
  /**
   * Schedule category — fires at a configurable time offset after a shift's
   * scheduled start, but targets the worker's manager(s) rather than the
   * worker, escalating a no-show.
   */
  ShiftStartAfterManager = 'SHIFT_START_AFTER_MANAGER',
  /**
   * Schedule category — fires at a configurable time offset before a shift's
   * scheduled start (e.g. 1 hour before start).
   */
  ShiftStartBefore = 'SHIFT_START_BEFORE'
}

