/** The error response of the time tracking update worker (submit time) mutation. */
export type TimeTracking_SubmitWorkerTimeError = TimeTracking_MutationError & {
  __typename?: 'TimeTracking_SubmitWorkerTimeError';
  /** Contains additional error details related to TimeTracking Update Worker */
  details?: Maybe<Scalars['String']['output']>;
  /**
   * ### Possible failure or error codes for an update worker (submit time) mutation.
   * *This list may be extended in the future. If an unknown error code is encountered, treat it as a `GENERAL_ERROR`.*
   *
   * - `GENERAL_ERROR`
   * - This error will be returned when we encounter an error that does not yet have a specific code attached to it.
   *
   * - `WORKER_NOT_FOUND`
   * - The specified worker does not exist in the workers store or the caller lacks access.
   *
   * - `UNAUTHORIZED`
   * - The caller is neither the worker (self) nor an admin and is not permitted to submit this worker's time.
   */
  errorCode: Scalars['TimeTracking_ErrorCode']['output'];
  /** Contains text description of error conditions related to TimeTracking Update Worker */
  message?: Maybe<Scalars['String']['output']>;
  /** Secondary error code related to TimeTracking Update Worker */
  subCode?: Maybe<Scalars['String']['output']>;
};

/** Input for the time tracking update worker (submit time) mutation. */
export type TimeTracking_SubmitWorkerTimeInput = {
  /**
   * Exclusive-end ISO date (YYYY-MM-DD) through which to submit time.
   * The client applies the +1-day / full-week math; Quantum Leap forwards
   * this value verbatim to TSheets. To submit through March 29, send 2026-03-30.
   */
  submittedTo: Scalars['String']['input'];
  /**
   * Worker identifier as exposed by the `timeTrackingWorkers` query.
   * This is the contactId for EMPLOYEE/VENDOR workers, or the qboUserId for
   * LEGACY_QBO_USER workers — not the underlying TSheets numeric user id.
   */
  workerId: Scalars['ID']['input'];
  /**
   * Type of the worker. Required to disambiguate which id column `workerId`
   * refers to and to locate the correct worker record.
   */
  workerType: TimeTracking_TimeForType;
};

/**
 * The success response of the time tracking update worker (submit time) mutation.
 *
 * Submit-time fields are returned in this self-contained payload and intentionally
 * do not extend `TimeTracking_Worker`. They will be folded into the worker type once
 * the submit-time data is migrated from TSheets into Quantum Leap.
 */
export type TimeTracking_SubmitWorkerTimePayload = TimeTracking_MutationSuccess & {
  __typename?: 'TimeTracking_SubmitWorkerTimePayload';
  /**
   * Exclusive end — time is approved through (approvedTo - 1 day).
   * Sourced from the TSheets response. May be null if unavailable or
   * the caller lacks permission to view approvals.
   */
  approvedTo?: Maybe<Scalars['String']['output']>;
  /**
   * Exclusive end — time is submitted through (submittedTo - 1 day).
   * Sourced from the TSheets response. May be null if unavailable.
   */
  submittedTo?: Maybe<Scalars['String']['output']>;
  /**
   * ### Possible success codes for an update worker (submit time) mutation.
   * *This list may be extended in the future. If an unknown code is encountered, treat it as `SUCCESS`*
   *
   * - `SUCCESS`
   * - The worker's time was submitted successfully.
   */
  successCode: Scalars['TimeTracking_SuccessCode']['output'];
  /** The worker identifier that was submitted, echoed from the input. */
  workerId: Scalars['ID']['output'];
  /** The worker type that was submitted, echoed from the input. */
  workerType: TimeTracking_TimeForType;
};

/** Result of the time tracking update worker (submit time) mutation. */
export type TimeTracking_SubmitWorkerTimeResult = TimeTracking_SubmitWorkerTimeError | TimeTracking_SubmitWorkerTimePayload;

