/** Input for querying workers in a company */
export type TimeTracking_WorkersQueryFilter = {
  /** Filter by group membership (returns workers in specified group) */
  groupId?: InputMaybe<Scalars['ID']['input']>;
  /**
   * Filter by whether workers have a group assignment
   * - `true`: Returns only workers WITH a group (memberOfGroup is not null)
   * - `false`: Returns only workers WITHOUT a group (memberOfGroup is null) - the "No Group" case
   * - `null` or omitted (default): Returns all workers regardless of group assignment
   */
  hasGroup?: InputMaybe<Scalars['Boolean']['input']>;
  /**
   * Filter by Intuit Identity Auth IDs.
   * Returns only workers whose identity auth ID matches any of the provided values.
   * - `null` or omitted (default): No filtering by identity auth ID
   */
  identityAuthIds?: InputMaybe<Array<Scalars['ID']['input']>>;
  /**
   * Filter by active status (defaults to `true` for active workers only)
   * - `true` (default): Returns only active workers
   * - `false`: Returns only inactive workers
   * - `null` (explicitly pass null): Returns all workers (both active and inactive)
   */
  isActive?: InputMaybe<Scalars['Boolean']['input']>;
  /**
   * Filter to only workers who have time tracking access enabled.
   * - `true`: Returns only workers with time tracking permission (can track time and have time tracked on their behalf)
   * - `false` or `null` or omitted (default): No filtering by time tracking permission
   */
  isTimeTrackingEnabled?: InputMaybe<Scalars['Boolean']['input']>;
  /** Filter by managed groups (returns workers who manage specified group) */
  managesGroupId?: InputMaybe<Scalars['ID']['input']>;
  /**
   * Search workers by name with partial case-insensitive match
   * - Searches across firstName, lastName, and displayName fields
   * - Returns workers whose name contains the provided string
   * - `null` or omitted: No name filtering is applied
   */
  searchText?: InputMaybe<Scalars['String']['input']>;
  /** Filter by worker type */
  types?: InputMaybe<Array<TimeTracking_TimeForType>>;
  /**
   * Batch query multiple workers by their individual filters.
   * Returns workers matching any of the provided worker filters.
   * - Each filter should specify both `id` and `type` for a specific worker
   * - Returns the union of all matching workers
   * - `null` or omitted: No batch filtering is applied
   *
   * Example: Fetch multiple specific workers in one query
   * ```
   * workerFilters: [
   *   { id: "400000001", type: EMPLOYEE },
   *   { id: "3", type: VENDOR },
   *   { id: "9341456048547404", type: LEGACY_QBO_USER }
   * ]
   * ```
   */
  workerFilters?: InputMaybe<Array<TimeTracking_WorkerQueryFilter>>;
};

